css=':root{--b:#2563eb;--i:#172033;--m:#59677c;--bg:#f7f9fc;--l:#dce4ef;--ok:#087443;--bad:#b42318}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--i);font:16px/1.65 system-ui,sans-serif}.top{background:linear-gradient(130deg,#0d1b36,#164898);color:white;padding:28px 0}.wrap{max-width:1160px;margin:auto;padding:0 20px}.layout{display:grid;grid-template-columns:230px 1fr;gap:27px;padding-top:28px}.side{height:max-content;position:sticky;top:10px;background:#fff;border:1px solid var(--l);padding:12px;border-radius:13px}.side a{display:block;padding:6px;text-decoration:none;color:var(--m);font-size:13px}.side a:hover{background:#eaf1ff;color:#164898}main{min-width:0}.hero,.card,details{background:#fff;border:1px solid var(--l);border-radius:14px;padding:20px;margin-bottom:17px}.hero{background:linear-gradient(130deg,#eaf2ff,#fff)}h1{font-size:clamp(30px,4vw,45px);line-height:1.1;margin:.3em 0}h2{margin-top:38px;line-height:1.2}h3{line-height:1.25}.muted{color:#d2e1ff}.tag{font-size:11px;font-weight:800;background:#e1ecff;color:#164898;border-radius:999px;padding:3px 7px}.impl{background:#dff7e9;color:#075a35}.missing{background:#ffe4e0;color:#9d1912}.call{border-left:5px solid var(--b);padding:14px 16px;background:#edf4ff;margin:17px 0}.call.ok{border-color:var(--ok);background:#effaf4}.call.no{border-color:var(--bad);background:#fff2f0}.facts,.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:12px;margin:17px 0}.fact{background:#fff;border:1px solid var(--l);border-radius:10px;padding:12px}.fact b{font-size:20px;color:#164898;display:block}table{width:100%;border-collapse:collapse;font-size:14px;margin:13px 0}th,td{border:1px solid var(--l);padding:9px;text-align:left;vertical-align:top}th{background:#edf3fb}code{background:#eef2f7;color:#a32c2c;border-radius:4px;padding:1px 4px}pre{background:#14213d;color:#e7effb;padding:15px;overflow:auto;border-radius:10px}details{padding:11px 14px}summary{cursor:pointer;font-weight:700}.button{display:inline-block;background:var(--b);color:white;border-radius:8px;padding:9px 13px;text-decoration:none;font-weight:700;font-size:14px}.links{display:flex;justify-content:space-between;margin:36px 0}.diagram{width:100%;background:#fff;border:1px solid var(--l);border-radius:13px;padding:10px;margin:15px 0}.diagram svg{width:100%;height:auto}.search{width:100%;padding:9px;border:1px solid var(--l);border-radius:7px}@media(max-width:800px){.layout{display:block}.side{position:static}.side nav{display:grid;grid-template-columns:repeat(2,1fr)}table{font-size:12px}.wrap{padding:0 12px}}'
