def nav():return '<aside class="side"><a href="README.html"><b>Course home</b></a><input id="q" class="search" oninput="f()" placeholder="Filter chapters"><nav>'+''.join(f'<a href="{a}">Part {i+1}: {b}</a>' for i,(a,b,c) in enumerate(chap))+''.join(f'<a href="{a}">{b}</a>' for a,b in [('development_decisions.html','Decision log'),('interview_preparation.html','Interview prep'),('glossary.html','Glossary'),('quick_revision.html','Revision'),('PROJECT_AUDIT.html','Project audit')])+'</nav></aside>'
def page(t,b,p='README.html',n='README.html'):return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+t+' | Credit Default Course</title><link rel="stylesheet" href="style.css"><script src="app.js"></script><body><header class="top"><div class="wrap"><b>Credit Default Project — evidence-led learning course</b><div class="muted">Static offline documentation · inspected 3 November 2026</div></div></header><div class="wrap layout">'+nav()+'<main>'+b+'<div class="links"><a class="button" href="'+p+'">← Previous</a><a class="button" href="'+n+'">Next →</a></div></main></div></body></html>'
def hero(k,t,l):return '<section class="hero"><span class="tag">'+k+'</span><h1>'+t+'</h1><p>'+l+'</p></section>'
def quiz():return '<h2>Check understanding</h2><p>Try each aloud before opening it: five beginner, five intermediate and two challenging questions.</p>'+''.join('<details><summary>'+q+'</summary><p>'+a+'</p></details>' for q,a in [('Beginner — What is the target?','<code>default.payment.next.month</code>: 1 means default, 0 no default.'),('Beginner — Is this transaction fraud?','No. Root project is next-month client default prediction.'),('Beginner — What is a feature?','An input clue such as PAY_0 or LIMIT_BAL.'),('Beginner — Why test data?','To estimate performance on records not used to fit.'),('Beginner — What limitation matters?','It is historical Taiwan 2005 data, not production lending data.'),('Intermediate — Evidence for claim?','Cite active root source, paired artifacts, data inspection or recomputed metrics.'),('Intermediate — What ranks thresholds?','ROC-AUC; active GridSearchCV uses it.'),('Intermediate — Why can accuracy mislead?','Always predicting no default yields 77.88% accuracy and zero recalls.'),('Intermediate — What is leakage?','Evaluation/future information influences fitting.'),('Intermediate — What must accompany model.pkl?','preprocessor.pkl because it produces the expected 42 features.'),('Challenge — Best improvement?','Select on train-only stratified CV, reserve test, then choose threshold/calibration by cost.'),('Challenge — Interview summary?','Educational default-risk prototype with evidence-based limits, not a production decision system.')])+'<div class="card"><b>Exercise:</b> Trace one input from web form through CustomData, preprocessor and predict_proba.</div>'
flow='<div class="diagram"><svg viewBox="0 0 880 160"><style>.b{fill:#edf4ff;stroke:#2563eb;stroke-width:2}.t{font:600 13px system-ui;fill:#172033}.s{font:11px system-ui;fill:#59677c}</style><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="#2563eb"/></marker></defs><g stroke="#2563eb" stroke-width="2" marker-end="url(#a)"><path d="M130 70H170"/><path d="M300 70H340"/><path d="M500 70H540"/><path d="M680 70H720"/></g><g class="b"><rect x="10" y="40" width="120" height="62" rx="9"/><rect x="170" y="40" width="130" height="62" rx="9"/><rect x="340" y="28" width="160" height="86" rx="9"/><rect x="540" y="28" width="140" height="86" rx="9"/><rect x="720" y="28" width="145" height="86" rx="9"/></g><g text-anchor="middle"><text class="t" x="70" y="66">UCI CSV</text><text class="s" x="70" y="84">30,000 rows</text><text class="t" x="235" y="66">Ingestion</text><text class="s" x="235" y="84">80/20 seed 42</text><text class="t" x="420" y="58">Preprocessor</text><text class="s" x="420" y="78">engineer, impute</text><text class="s" x="420" y="94">encode, scale</text><text class="t" x="610" y="58">Grid search</text><text class="s" x="610" y="78">6 families</text><text class="s" x="610" y="94">ROC-AUC, cv=2</text><text class="t" x="792" y="58">Artifacts</text><text class="s" x="792" y="78">CatBoost +</text><text class="s" x="792" y="94">preprocessor</text></g><text class="s" x="440" y="145" text-anchor="middle">Winner selection by test ROC-AUC is a documented weakness.</text></svg></div>'
texts=[('Default prediction, not transaction fraud','The root app estimates whether a client will default on the next payment. It does not inspect an individual transaction for fraud.','A feature is an input clue: credit limit, demographics, repayment status, bill or payment. A label/target is the historical answer. This is supervised binary classification: default=1 and no default=0. Rules miss interactions among these signals; a trained model learns patterns from labelled examples. Learning a pattern is not proof of causation, fairness, or suitability for automatic lending.','<table><tr><th>Question</th><th>Active root project</th><th>Transaction fraud</th></tr><tr><td>Unit judged</td><td>Client next-month payment default</td><td>One transaction</td></tr><tr><td>Inputs</td><td>Six-month credit history</td><td>Merchant/device/time/location</td></tr><tr><td>Artifact</td><td>CatBoost default classifier</td><td>None in root flow</td></tr></table>'),('The verified UCI dataset','The active ingestion code reads <code>notebooks/data/UCI_Credit_Card.csv</code>. These facts were recomputed from that file.','The file has 30,000 rows and 25 columns; 23,364 no-default cases (77.88%) and 6,636 defaults (22.12%); zero raw missing cells, duplicate rows and duplicate IDs. It records Taiwan credit-card clients and six months in 2005. Numeric storage does not make codes continuous: SEX, EDUCATION and MARRIAGE are categories.','<table><tr><th>Columns</th><th>Meaning</th><th>Project use</th></tr><tr><td>ID</td><td>Record identifier</td><td>Dropped.</td></tr><tr><td>LIMIT_BAL, AGE</td><td>Credit limit, age</td><td>Numeric inputs.</td></tr><tr><td>SEX, EDUCATION, MARRIAGE</td><td>Profile category codes</td><td>Recoded then one-hot encoded.</td></tr><tr><td>PAY_0, PAY_2…PAY_6</td><td>Repayment status Sep–Apr 2005</td><td>Raw plus delay summaries.</td></tr><tr><td>BILL_AMT1…6, PAY_AMT1…6</td><td>Bills and payments</td><td>Raw plus ratios/means/trends.</td></tr><tr><td>default.payment.next.month</td><td>0/1 outcome</td><td>Target.</td></tr></table><div class="call no"><span class="tag missing">LIMITATION</span> Historical one-population academic data is not live representative lending data.</div>'),('Machine learning from zero','The vocabulary needed to explain implementation rather than memorise terms.','AI is broad; machine learning learns patterns from examples. Supervised learning has answers, as here. Unsupervised learning finds structure without labels; reinforcement learning learns actions from rewards; neither is implemented. Regression predicts a numeric quantity; classification chooses a category. An algorithm is the recipe; a trained model is that recipe after fitting learned parameters. Hyperparameters like depth are selected before/during search.','<table><tr><th>Concept</th><th>Meaning here</th></tr><tr><td>Training/test</td><td>Practice examples / unseen exam.</td></tr><tr><td>Loss/optimisation</td><td>Measure error / adjust learned parameters to reduce it.</td></tr><tr><td>Overfitting</td><td>Memorising quirks rather than generalising.</td></tr><tr><td>Underfitting</td><td>Model too simple to learn signal.</td></tr><tr><td>Bias/variance</td><td>Too rigid / too sensitive to sample quirks.</td></tr><tr><td>Cross-validation</td><td>Rotate train/validation folds to estimate stability.</td></tr></table>'),('Exploratory data analysis','The rich EDA is in <code>UCI/01_cleaning_eda_feature_engineering.ipynb</code>; root training does not execute it.','EDA checks what exists before modelling: shape/types/nulls/duplicates, target distribution, distributions, outliers, correlations and group rates. Mean is arithmetic average, median middle sorted value, mode most common. Variance measures squared spread; standard deviation is its square root. Percentiles locate a value. Correlation is linear association—not causation.','<table><tr><th>Observed check</th><th>Result</th></tr><tr><td>Data quality</td><td>30k × 25; zero nulls/duplicate rows/IDs.</td></tr><tr><td>Limit distribution</td><td>10,000–1,000,000; mean 167,484, median 140,000, so right-skewed.</td></tr><tr><td>Top raw target correlations</td><td>PAY_0 .3248, PAY_2 .2636, PAY_3 .2353.</td></tr><tr><td>PAY_0=2 group</td><td>69.14% default rate; association, not causation.</td></tr></table><div class="call ok"><span class="tag impl">NOTEBOOKS</span> Histograms, boxplots, heatmaps and group plots exist as EDA, but are not automated quality gates.</div>'),('Preprocessing and feature engineering','The active sklearn transformer turns 23 supplied raw features into 42 model columns.','Actual order: drop ID; map EDUCATION 0/5/6→4 and MARRIAGE 0→3; create utilisation, six payment ratios, payment-status summaries, bill/payment means and slopes, flags; select 16 engineered values; then impute, encode and scale. <code>consecutive_delays</code> is calculated but omitted, while <code>months_with_delays</code> uses the same count and is selected.','<table><tr><th>Operation</th><th>Exact approach</th><th>Why</th></tr><tr><td>Numeric</td><td>median imputer → StandardScaler</td><td>Defensive missing handling and comparable numeric scale.</td></tr><tr><td>Categorical</td><td>most-frequent imputer → OHE(drop first, ignore unknown) → sparse-safe scale</td><td>Represent codes without arbitrary order.</td></tr><tr><td>Utilisation</td><td>BILL_AMT1/LIMIT_BAL if positive</td><td>Latest exposure relative to limit.</td></tr><tr><td>Payment ratio</td><td>PAY_AMTi/BILL_AMTi if positive</td><td>Payment relative to bill.</td></tr><tr><td>Trend</td><td>np.polyfit slope across six periods</td><td>Rising/falling bill/payment pattern.</td></tr></table><p>StandardScaler computes (x−training mean)/training standard deviation. MinMaxScaler maps a range, RobustScaler uses median/IQR; neither is active. Fitting transformers on test data leaks information. Root fitting is train-only, but preprocessing sits outside GridSearchCV folds: improve with one estimator+preprocessor pipeline.</p>'),('Class imbalance','A high accuracy can still fail to catch the people of interest.','Defaults are the minority (22.12%). An all-no-default classifier gets 77.88% accuracy and zero default recall. Oversampling copies minority rows; undersampling discards majority rows; SMOTE synthesises minority neighbours; ADASYN focuses harder areas; class weights penalise minority errors more; threshold adjustment converts probability at a non-.5 cutoff. All have trade-offs.','<table><tr><th>Actual root choice</th><th>Evidence</th><th>Implication</th></tr><tr><td>No SMOTE</td><td>Trainer logs “Proceeding without SMOTE.”</td><td>Natural distribution retained.</td></tr><tr><td>No active class weights</td><td>Estimator constructors omit them.</td><td>Recall at .5 is only .359482.</td></tr><tr><td>Non-stratified split</td><td>train_test_split has no stratify argument.</td><td>Class proportion can vary by split.</td></tr></table><div class="call"><span class="tag">LEAKAGE RULE</span> Never resample before split; resample only training folds because synthetic/copy relationships can leak into evaluation.</div>'),('Candidate models and saved CatBoost','All six candidates are in <code>model_trainer.py</code>; <code>artifacts/model.pkl</code> loads as CatBoostClassifier.','Logistic regression makes a linear weighted probability; Random Forest averages varied trees; Gradient Boosting and AdaBoost add learners sequentially; XGBoost and CatBoost are powerful boosted-tree variants. Trees can learn nonlinear interactions in tabular data; they can also overfit and importance is not causation.','<table><tr><th>Model</th><th>Actual search</th></tr><tr><td>Logistic Regression</td><td>C .1/1/10; L2/liblinear.</td></tr><tr><td>Random Forest</td><td>50/100 trees; depth 10/15.</td></tr><tr><td>Gradient Boosting</td><td>50/100; rate .1/.2; depth 3/5.</td></tr><tr><td>AdaBoost</td><td>50/100; rate .5/1.</td></tr><tr><td>XGBoost</td><td>50/100; depth 3/6; rate .1/.2.</td></tr><tr><td>CatBoost</td><td>50/100 iterations; depth 4/6; rate .1/.2.</td></tr></table><p>Saved CatBoost: 100 iterations, depth 4, rate .1, seed 42. Top internal importance: PAY_0 22.87, max_payment_delay 11.96, utilisation 4.92, PAY_2 4.79, LIMIT_BAL 4.39. SVM/KNN/Naive Bayes/LightGBM are alternatives, not root implementations.</p>'),('From CSV to prediction','The actual root flow, not an idealised or archived one.','Run <code>src/pipeline/train_pipeline.py</code>: DataIngestion writes raw/train/test CSVs; DataTransformation fits preprocessor on train and transforms test; ModelTrainer grid-searches six models and saves winner. PredictPipeline loads paired pickles, transforms a one-row DataFrame and uses predict/predict_proba. Flask/API/Next interfaces call it.','<table><tr><th>Vocabulary</th><th>Meaning</th></tr><tr><td>Pipeline</td><td>Ordered transformations; root uses it for preprocessing.</td></tr><tr><td>ColumnTransformer</td><td>Routes numeric/categorical fields differently.</td></tr><tr><td>fit</td><td>Learn statistics/parameters.</td></tr><tr><td>transform</td><td>Apply learned conversion.</td></tr><tr><td>fit_transform</td><td>Fit then convert training rows.</td></tr><tr><td>predict/predict_proba</td><td>Hard class / probability vector.</td></tr></table><div class="call no"><span class="tag missing">GAP</span> Estimator is not inside GridSearchCV preprocessing pipeline; no artifact registry, schema gate or monitoring exists.</div>'),('Metrics and verified results','Metrics below were recomputed from paired saved artifacts on 6,000 test rows at the default .50 cutoff.','Confusion matrix: TN 4,449, FP 238, FN 841, TP 472. A false negative is a missed default; a false positive is an unnecessary flag. Which harm matters most requires business/fairness/legal judgement, not maths alone.','<table><tr><th>Metric</th><th>Formula/meaning</th><th>Verified result</th></tr>'+''.join('<tr><td>'+k+'</td><td>'+({'ROC-AUC':'Ranks positives above negatives across thresholds.','accuracy':'(TP+TN)/all.','precision':'TP/(TP+FP): flags that are correct.','recall':'TP/(TP+FN): defaults caught.','F1':'2PR/(P+R), harmonic balance.','average precision':'Precision-recall summary.','balanced accuracy':'(recall+specificity)/2.','MCC':'Uses all matrix cells; correlation-like.','log loss':'Probability-quality penalty.'}[k])+'</td><td>'+v+'</td></tr>' for k,v in facts.items())+'</table><p>ROC plots TPR versus FPR; .5 AUC is random and 1 perfect. PR curve plots precision versus recall and can help with minority positives. Calibration asks whether a .70 score implies about 70% observed defaults. The display risk bands 40/70 do not change the model’s .5 class decision.</p><div class="call no"><span class="tag missing">NOT IMPLEMENTED</span> No active PR/ROC/calibration plot, threshold search, cost analysis or saved evaluation report.</div>'),('Grid search and selection','Parameters are learned during fit; hyperparameters such as depth and iteration count are choices searched around fit.','<code>evaluate_models</code> creates <code>GridSearchCV(model, grid, cv=2, scoring="roc_auc", n_jobs=-1)</code> for each of six families, fits transformed train data, stores best estimators and records test ROC-AUC. The trainer chooses maximum test ROC-AUC and serialises that model.','<table><tr><th>Choice</th><th>Assessment</th></tr><tr><td>ROC-AUC scoring</td><td>Reasonable ranking objective, but not cost/recall threshold policy.</td></tr><tr><td>cv=2</td><td>Fast, but less stable; code does not set StratifiedKFold.</td></tr><tr><td>No early stopping</td><td>Fixed grid, no validation-based stopping.</td></tr><tr><td>Max test score selects winner</td><td>Main concern: test is no longer strictly final untouched evaluation.</td></tr></table><p>Better: stratified train/test split; Pipeline(preprocess, model); stratified CV/search only in train; choose/calibrate threshold on validation; report once on untouched test. Grid search is exhaustive only over supplied small grids; RandomizedSearchCV can explore larger spaces.</p>'),('Active code walkthrough','Follow the root implementation; duplicated alternatives are not evidence for the saved root artifact.','<code>data_ingestion.py</code> loads/splits. <code>data_transformation.py</code> defines the custom feature engineer and sklearn ColumnTransformer. <code>model_trainer.py</code> sets candidates/grids and saves winner. <code>utils.py</code> serialises and evaluates. <code>train_pipeline.py</code> orchestrates. <code>predict_pipeline.py</code> maps web/API inputs to DataFrame and predicts. <code>application.py</code> is Flask routes; <code>api/predict.py</code> handles JSON; <code>app/</code> is Next.js UI.','<pre>model = load_object(model_path)\npreprocessor = load_object(preprocessor_path)\ndata_scaled = preprocessor.transform(features)\npreds = model.predict(data_scaled)\nproba = model.predict_proba(data_scaled)[:, 1]</pre><p>A DataFrame is a labelled table; a NumPy array is a numerical matrix. A function is reusable named behaviour; a class groups data/behaviour; <code>CustomData(...)</code> instantiates an object; a method belongs to an object. Dataclasses here hold config. Random state supports reproducibility. SHAP/matplotlib imports and an image exist, but active trainer does not generate SHAP output.</p>'),('Prototype to responsible system','There are local serving interfaces, not a safe automated lending system.','Implemented: pickle persistence; paired preprocessing; Flask form; JSON handler; Next.js form. Missing: schema/range/domain validation, authentication, rate limiting, safe errors, restricted CORS, audit logs, drift/retraining, calibration, monitoring, fairness testing and governance. The API returns tracebacks and uses CORS *—fine for prototype diagnosis, not production.','<table><tr><th>Production layer</th><th>Needed action</th></tr><tr><td>Input</td><td>Schema/range validation, consent, auth, rate limit.</td></tr><tr><td>Model</td><td>Versioned packaged pipeline, calibration, threshold policy.</td></tr><tr><td>Decision</td><td>Human review, reason/appeal process; never automatic academic-data lending decision.</td></tr><tr><td>Operations</td><td>Secure logs, drift/performance/fairness monitoring, feedback/retraining controls.</td></tr></table><div class="call no"><span class="tag missing">RESPONSIBLE USE</span> Historical demographics and credit outcomes require legal, privacy, fairness and human-oversight review.</div>')]
for i,(title,lead,para,extra) in enumerate(texts):
 b=hero('Part '+str(i+1),title,lead)+'<div class="facts"><div class="fact"><b>IMPLEMENTED</b><span>active root evidence</span></div><div class="fact"><b>CONCEPTUAL</b><span>clearly labelled context</span></div><div class="fact"><b>LIMITATION</b><span>never fabricated</span></div></div><h2>What this means</h2><p>'+para+'</p><h2>Evidence and detail</h2>'+extra+quiz()
 p=chap[i-1][0] if i else 'README.html';n=chap[i+1][0] if i+1<len(chap) else 'development_decisions.html';(o/chap[i][0]).write_text(page(title,b,p,n),encoding='utf8')
read=hero('Course home','UCI Credit Card Default Prediction learning website','Self-contained documentation based on active source, raw data, artifacts, notebooks, configs and interfaces.')+'<div class="facts">'+''.join('<div class="fact"><b>'+v+'</b><span>'+k+'</span></div>' for k,v in [('records','30,000'),('model inputs','42'),('saved model','CatBoost'),('ROC-AUC',facts['ROC-AUC'])])+'</div>'+flow+'<h2>Suggested learning order</h2><p>Read Parts 1–3 for absolute-zero foundations; 4–10 for the actual data/model/evaluation; 11–12 for code and production limits. Then use decision log, glossary, revision and interview practice. Estimated study: 8–12 focused hours.</p><div class="grid">'+''.join('<a class="card" data-s="'+b+'" href="'+a+'"><b>Part '+str(i+1)+': '+b+'</b><p>'+c+'</p></a>' for i,(a,b,c) in enumerate(chap))+''.join('<a class="card" href="'+a+'"><b>'+b+'</b></a>' for a,b in [('development_decisions.html','Decision log'),('interview_preparation.html','Interview preparation'),('glossary.html','Glossary'),('quick_revision.html','Quick revision'),('PROJECT_AUDIT.html','Project audit')])+'</div><h2>Checklist</h2><details open><summary>Before you say you know the project</summary><p>□ I distinguish default from fraud. □ I can name target/input families. □ I can trace CSV to API. □ I explain the confusion matrix. □ I state selection/leakage limitations. □ I do not call it production-ready.</p></details>'
decisions=[('Dataset','UCI CSV hard-coded in ingestion','Accessible labelled benchmark; dated/narrow','Use governed current representative data.'),('Cleaning','EDUCATION 0/5/6→4; MARRIAGE 0→3','Simplifies anomalous codes; loses distinctions','Document codebook/unknown policy.'),('Split','80/20 seed 42, no stratify','Reproducible but proportions can vary','Stratify and record split manifest.'),('Features','Manual raw + engineered lists','Captures patterns; duplicate delay count logic','Feature registry/unit tests.'),('Preprocess','Median/OHE/StandardScaler','Consistency; CV fold leakage risk','Unified pipeline inside CV.'),('Imbalance','No SMOTE or weights','Natural data; recall low at .5','Compare within training folds.'),('Selection','ROC-AUC cv=2; max test score','Simple; test influences choice','Train-only stratified CV then test once.'),('Threshold','.5 class; 40/70 display bands','Simple; not cost-informed','Calibration/cost/capacity threshold.'),('Serving','Separate pickles + Flask/API/Next','Working demo; version mismatch risk','Versioned packaged pipeline + validation.')]
dec=hero('Reference','Development decision log','Verified choices separated from interpretations; original intent is never fabricated.')+'<table><tr><th>Decision</th><th>Chosen / evidence</th><th>Trade-off</th><th>Better today</th></tr>'+''.join('<tr><td>'+a+'</td><td>'+b+'</td><td>'+c+'</td><td>'+d+'</td></tr>' for a,b,c,d in decisions)+'</table><h2>If rebuilding in 2026</h2><ol><li>Start with current permitted data and a data contract.</li><li>Put transforms/resampling/estimator in one versioned pipeline and stratified CV.</li><li>Reserve test data and choose threshold/calibration against documented harms and review capacity.</li><li>Add schema, artifact, integration/security tests.</li><li>Add fairness, monitoring, drift alerts, human review and appeals.</li></ol><div class="call no"><span class="tag missing">HONEST ASSESSMENT</span> This is an educational end-to-end prototype, not evidence of fair, calibrated, secure or compliant lending automation.</div>'
terms=[('Accuracy','Correct predictions divided by all predictions.'),('AUC','Area under curve; ROC-AUC measures ranking across cutoffs.'),('Bias','Error from overly restrictive assumptions.'),('Binary classification','Choosing two labels.'),('Calibration','Whether probabilities match observed frequencies.'),('CatBoost','Saved gradient-boosted classifier.'),('Class imbalance','Unequal class counts.'),('ColumnTransformer','Sklearn router for column groups.'),('Confusion matrix','TP/TN/FP/FN count table.'),('Cross-validation','Rotated train/validation splits.'),('Data leakage','Evaluation/future information affects fitting.'),('Feature','Model input variable.'),('F1','Harmonic mean of precision and recall.'),('fit','Learn statistics/parameters from data.'),('GridSearchCV','Search supplied hyperparameter combinations with CV.'),('Hyperparameter','Chosen setting such as tree depth.'),('Inference','Prediction from a fitted model.'),('Log loss','Probability-quality error.'),('One-hot encoding','Categories converted to indicator columns.'),('Overfitting','Memorising sample quirks.'),('Precision','Correct positives divided by predicted positives.'),('Recall','Correct positives divided by actual positives.'),('ROC curve','TPR/FPR across thresholds.'),('StandardScaler','Mean-center and scale by training standard deviation.'),('Target','Known answer predicted by supervised learning.'),('Threshold','Probability cutoff for hard class.')]
